<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../config/audit.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/report_error.php';
try{if($_SERVER['REQUEST_METHOD']!=='POST')jsonResponse(['success'=>false,'message'=>'Method not allowed'],405);$auth=requireAuth();$uid=authTenantId($auth);$actorId=authActorId($auth);$d=json_decode(file_get_contents('php://input'),true)?:[];$id=(int)($d['id']??0);$reason=trim((string)($d['reason']??''));if($id<=0||mb_strlen($reason)<20||mb_strlen($reason)>1000)throw new InvalidArgumentException('A reopening reason of at least 20 characters is required');$c=db();requirePermission($c,$uid,'reports.view');$role=currentUserRole($c,$uid);$c->begin_transaction();$s=$c->prepare('SELECT * FROM erp_vat_periods WHERE id=? AND user_id=? FOR UPDATE');$s->bind_param('ii',$id,$uid);$s->execute();$period=$s->get_result()->fetch_assoc();$s->close();if(!$period||!in_array($period['status'],['LOCKED','FILED'],true))throw new DomainException('Only locked or filed VAT periods can be reopened');if($period['status']==='FILED'&&$role!=='ADMINISTRATOR')throw new DomainException('Only an administrator can reopen a filed VAT period');$s=$c->prepare("SELECT id FROM erp_filing_archives WHERE user_id=? AND declaration_type='VAT' AND source_entity_id=? ORDER BY filing_sequence DESC LIMIT 1");$s->bind_param('ii',$uid,$id);$s->execute();$archiveId=$s->get_result()->fetch_assoc()['id']??null;$s->close();$previous=$period['status'];$s=$c->prepare("UPDATE erp_vat_periods SET status='REVIEWED',locked_by=NULL,locked_at=NULL,filed_by=NULL,filed_at=NULL WHERE id=? AND user_id=?");$s->bind_param('ii',$id,$uid);$s->execute();$s->close();$s=$c->prepare("INSERT INTO erp_period_reopenings(user_id,period_type,period_id,previous_status,reason,prior_filing_archive_id,reopened_by,reopened_by_role) VALUES(?,'VAT',?,?,?,?,?,?)");$s->bind_param('iissiis',$uid,$id,$previous,$reason,$archiveId,$actorId,$role);$s->execute();$reopeningId=(int)$s->insert_id;$s->close();auditLog($c,$uid,$actorId,'VAT_PERIOD.REOPENED','VAT_PERIOD',$id,$period,['status'=>'REVIEWED','reason'=>$reason,'reopening_id'=>$reopeningId,'prior_filing_archive_id'=>$archiveId]);$c->commit();jsonResponse(['success'=>true,'id'=>$id,'status'=>'REVIEWED','reopening_id'=>$reopeningId]);
}catch(Throwable $e){if(isset($c))try{$c->rollback();}catch(Throwable $ignored){}reportFailureResponse($e,'Could not reopen the VAT period.','VAT_PERIOD_REOPEN_FAILED');}
